import { useSelector, useDispatch } from 'react-redux';
import { selectUser, logout } from './authSlice';

export function useAuth() {
  const dispatch = useDispatch();
  const user = useSelector(selectUser);

  const isAuthenticated = !!user;

  const requireAuth = () => {
    if (!isAuthenticated) {
      throw new Error('Unauthorized — please log in');
    }
  };

  return {
    user,
    isAuthenticated,
    requireAuth,
    logout: () => dispatch(logout()),
  };
}

import { useAuth } from './hooks/useAuth';

function Dashboard() {
  const { user, isAuthenticated, logout } = useAuth();

  if (!isAuthenticated) return <Login />;

  return (
    <div>
      <h1>Welcome {user.name}</h1>
      <button onClick={logout}>Log out</button>
    </div>
  );
}

import { useDispatch, useSelector } from 'react-redux';
import { login, selectAuth } from './authSlice';

export function useLogin() {
  const dispatch = useDispatch();
  const { loading, error, token } = useSelector(selectAuth);

  const submit = (credentials) => dispatch(login(credentials));

  return { submit, loading, error, token };
}
